def replace_many(text, mapping):
    items = sorted(mapping.items(), key=lambda kv: len(kv[0]), reverse=True)
    placeholders = []
    for i, (src, dst) in enumerate(items):
        if src not in text:
            continue
        token = f"__BI_U_{i}__"
        text = text.replace(src, token)
        placeholders.append((token, dst))
    for token, dst in placeholders:
        text = text.replace(token, dst)
    return text


for lang in LANGS:
    for rel, key in PAGES.items():
        path = Path(lang) / rel / "index.html"
        if not path.exists():
            raise SystemExit(f"Missing generated utility page: {path}")
        text = path.read_text(encoding="utf-8")
        text = replace_many(text, T[lang][key])
        path.write_text(text, encoding="utf-8")

        check = path.read_text(encoding="utf-8")
        if '<html lang="' + lang + '">' not in check:
            raise SystemExit(f"Wrong lang attribute: {path}")
        if "noindex" not in check:
            raise SystemExit(f"Utility page lost noindex: {path}")

print("OK: ES/PT/IT/FR utility pages localized.")
